/* CONFIG - edit these, then attach your own credentials.
   Never paste API keys into this node in production: use n8n credentials
   or environment variables (documented in docs/N8N-IMPLEMENTATION.md). */
const CONFIG = {
  SUPABASE_URL: $env.SUPABASE_URL || "YOUR_SUPABASE_URL",
  SUPABASE_SERVICE_KEY: $env.SUPABASE_SERVICE_KEY || "YOUR_SERVICE_KEY",
  LEADS_TABLE: "leads",
  BOOKING_URL: "YOUR_BOOKING_URL",
  BUSINESS_NAME: "YOUR BUSINESS NAME"
};
const H = this.helpers;
const HDRS = { apikey: CONFIG.SUPABASE_SERVICE_KEY, Authorization: "Bearer " + CONFIG.SUPABASE_SERVICE_KEY, "Content-Type": "application/json" };
const b = $input.first().json.body || {};
const s = (v, m) => String(v == null ? "" : v).slice(0, m || 300).trim();

// 1. honeypot: accept silently, store nothing
if (s(b.website, 50) !== "") return [{ json: { ok: true, valid: false, reason: "honeypot" } }];

// 2. validate + normalize
const email = s(b.workEmail, 254).toLowerCase();
const lead = {
  business_name: s(b.businessName, 200), contact_name: s(b.contactName, 200), email,
  phone: s(b.phone, 40).replace(/[^0-9+()\-. ]/g, ""), industry: s(b.industry, 60),
  team_size: s(b.teamSize, 30), lead_volume: s(b.monthlyLeadVolume, 30),
  current_systems: s(b.currentSystems, 400), problem: s(b.primaryProblem, 2000),
  sms_consent: b.smsConsent === true, status: "new",
  source: (typeof b.source === "object" && b.source) ? b.source : {}
};
if (!lead.business_name || !lead.contact_name || !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)
    || lead.phone.replace(/[^0-9]/g, "").length < 10 || !lead.industry || lead.problem.length < 5) {
  return [{ json: { ok: false, valid: false, reason: "validation" } }];
}

// 3. correlation id + dedupe hash
const djb2 = t => { let h = 5381; for (let i = 0; i < t.length; i++) h = ((h << 5) + h + t.charCodeAt(i)) >>> 0; return h.toString(16); };
lead.submission_hash = djb2(email + "|" + lead.business_name + "|" + lead.problem.slice(0, 100));
const correlation = "la-" + Date.now().toString(36) + "-" + lead.submission_hash.slice(0, 6);

// 4. dedupe window: same email within 24h -> idempotent ok, no second insert/email
const since = new Date(Date.now() - 86400000).toISOString();
try {
  const q = await H.httpRequest({ url: CONFIG.SUPABASE_URL + "/rest/v1/" + CONFIG.LEADS_TABLE + "?email=eq." + encodeURIComponent(email) + "&created_at=gte." + since + "&select=id&limit=1", headers: HDRS, json: true });
  if (Array.isArray(q) && q.length) return [{ json: { ok: true, valid: false, reason: "duplicate", correlation } }];
} catch (e) { /* dedupe store unavailable: proceed rather than lose the lead */ }

// 5. store
let stored = "none";
try {
  await H.httpRequest({ method: "POST", url: CONFIG.SUPABASE_URL + "/rest/v1/" + CONFIG.LEADS_TABLE, headers: HDRS, body: lead, json: true });
  stored = CONFIG.LEADS_TABLE;
} catch (e) { stored = "FAILED: " + String(e.message || e).slice(0, 120); }

// 6. prepare notification + confirmation (notification failure must not lose the lead:
//    the insert above already happened; email nodes run with onError=continue)
return [{ json: {
  ok: true, valid: true, correlation, stored,
  subject: "NEW LEAD: " + lead.business_name + " (" + lead.industry + ")",
  body: "New audit/lead request\n\n" + JSON.stringify(lead, null, 2) + "\n\nstored: " + stored + "\ncorrelation: " + correlation,
  lead_email: email,
  confirm_subject: "Your request is in",
  confirm_body: "Hi " + lead.contact_name.split(" ")[0] + ",\n\nYour request for " + lead.business_name + " was received. This confirms receipt, not acceptance of work.\n\nBook a time here: " + CONFIG.BOOKING_URL + "\n\n" + CONFIG.BUSINESS_NAME
} }];
